CREATE TABLE IF NOT EXISTS commercial_awards(id TEXT PRIMARY KEY,customer_id TEXT NOT NULL REFERENCES customers(id),reference TEXT NOT NULL UNIQUE COLLATE NOCASE,quotation_id TEXT NOT NULL REFERENCES commercial_records(id),version TEXT NOT NULL,evidence TEXT NOT NULL,snapshot TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(quotation_id,version));
CREATE TABLE IF NOT EXISTS commercial_award_sources(award_id TEXT NOT NULL REFERENCES commercial_awards(id),record_id TEXT NOT NULL REFERENCES commercial_records(id),PRIMARY KEY(award_id,record_id));
CREATE TABLE IF NOT EXISTS commercial_handovers(id TEXT PRIMARY KEY,award_id TEXT NOT NULL REFERENCES commercial_awards(id),project_id TEXT NOT NULL REFERENCES projects(id),workstream TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','rejected')),requested_by TEXT NOT NULL REFERENCES users(id),decided_by TEXT REFERENCES users(id),decision_note TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,decided_at TEXT,UNIQUE(award_id,workstream),UNIQUE(award_id,project_id));
CREATE TABLE IF NOT EXISTS commercial_delivery_audit(id TEXT PRIMARY KEY,customer_id TEXT NOT NULL REFERENCES customers(id),award_id TEXT REFERENCES commercial_awards(id),actor_id TEXT NOT NULL REFERENCES users(id),action TEXT NOT NULL,snapshot TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS commercial_handovers_project ON commercial_handovers(project_id,status);
CREATE TRIGGER IF NOT EXISTS commercial_award_immutable BEFORE UPDATE ON commercial_awards BEGIN SELECT RAISE(ABORT,'Accepted award is immutable; register a new version'); END;
CREATE TABLE IF NOT EXISTS commercial_record_links(child_id TEXT NOT NULL REFERENCES commercial_records(id),parent_id TEXT NOT NULL REFERENCES commercial_records(id),PRIMARY KEY(child_id,parent_id),CHECK(child_id<>parent_id));
CREATE TRIGGER IF NOT EXISTS commercial_handover_task_guard BEFORE UPDATE OF status ON work_tasks WHEN NEW.status IN ('in_progress','done') AND EXISTS(SELECT 1 FROM pm_task_links l JOIN commercial_handovers h ON h.project_id=l.project_id WHERE l.task_id=NEW.id AND h.status<>'accepted') BEGIN SELECT RAISE(ABORT,'Commercial handover acceptance required'); END;
CREATE TRIGGER IF NOT EXISTS commercial_handover_gate_guard BEFORE UPDATE OF stage ON pm_profiles WHEN NEW.stage<>OLD.stage AND EXISTS(SELECT 1 FROM commercial_handovers h WHERE h.project_id=NEW.project_id AND h.status<>'accepted') BEGIN SELECT RAISE(ABORT,'Commercial handover acceptance required'); END;
